'use strict';
const prompt=`你是有来源的学习游戏编制助手。请将我提供的材料转成一个JSON内容包，严格保持示例结构，不生成代码。所有面向玩家的标题、叙述、任务、解释、来源说明必须用简体中文。引擎只支持：四类能力派送（rules/predict/generate/agent）、四步有序工作流与权限开关、采用率与人工复核收益模型、四选二迁移挑战。不适配这些玩法的材料必须返回 {"unsupported":true,"reason":"说明原因"}。不得编造知识或来源。答案与解释引用sources中的ID。考纲只用于映射范围，不作为每个知识答案的充分依据。数值是明确标注的教学假设。要求baseline>minutes>review>=0，人数/工作日/小时成本为正，quality>=floor且均在0到100，adoption在10到100。每个迁移挑战恰好两项required=true。知识改变必须使用新id。完成后仍需人工核对，不要声称官方题目或学习效果已获验证。

内容包结构示例：
`;
function materials(){
 modal('更换学习材料',`<h2>一套世界，换一份知识。</h2><p>当前可导入 <b>经过核对的结构化内容包</b>，替换任务、参数、角色和反馈。任意PDF自动生成、实时自由对话尚未接入。不要把这里的格式校验当作事实校验。</p><div class="warning">本版没有在线模型。可以复制下方提示词与示例到你使用的AI，附上学习材料，得到JSON后人工核对并导入。不支持此玩法的材料应退回，不能硬编。</div><div class="material-nav"><button id="copyPrompt">复制AI编制提示词</button><button id="samplePack">填入另一份示例</button><button id="downloadPack">下载当前内容包</button></div><label class="material-label" for="packJson">结构化内容包（最多 100 KB）</label><textarea id="packJson" spellcheck="false"></textarea><div id="importError" class="error" role="alert"></div><label class="switchline"><input type="checkbox" id="reviewed">我已核对来源、答案与教学假设，理解校验不能证明知识正确</label><div class="actions"><label class="file-button outline">选择内容包文件<input id="fileInput" type="file" accept=".json,application/json" aria-label="选择内容包文件"></label><button id="importPack" class="primary">校验并装入副本 →</button></div><p class="smallcopy">导入仅保留在当前页面；请下载内容包以便下次使用。存档按内容包ID区分。若更改知识与规则，必须使用新的ID。</p>`);
 $('packJson').value=JSON.stringify(pack,null,2);
 $('copyPrompt').onclick=async()=>{const t=prompt+JSON.stringify(QUEST_PACKS[0],null,2)+'\n\n学习材料：\n[在这里粘贴有出处的材料原文]';try{await navigator.clipboard.writeText(t);toast('提示词与示例已复制，附上材料后即可使用。');}catch{download('knowledge-quest-authoring-prompt.txt',t,'text/plain');toast('已下载提示词。');}};
 $('samplePack').onclick=()=>{$('packJson').value=JSON.stringify(QUEST_PACKS.find(p=>p.id!==pack.id)||QUEST_PACKS[0],null,2);$('reviewed').checked=false;};
 $('downloadPack').onclick=()=>download('knowledge-quest-content-pack.json',JSON.stringify(pack,null,2),'application/json');
 $('fileInput').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>100000){$('importError').textContent='文件超过 100 KB，请缩小范围。';return;}try{$('packJson').value=await f.text();$('reviewed').checked=false;}catch{$('importError').textContent='文件读取失败，请重新选择或直接粘贴内容。';}};
 $('importPack').onclick=()=>{const raw=$('packJson').value;let p;try{if(new TextEncoder().encode(raw).length>100000)throw Error('内容超过 100 KB。');p=JSON.parse(raw);}catch(e){$('importError').textContent=new TextEncoder().encode(raw).length>100000?'内容超过100 KB，请缩小范围。':'内容格式不正确，请检查引号、逗号与括号是否完整。';return;}const errors=E.validate(p);if(errors.length){$('importError').textContent=errors.join(' / ');return;}const existing=packs.find(x=>x.id===p.id);if(existing&&JSON.stringify(existing)!==JSON.stringify(p)){$('importError').textContent='此ID已存在且内容不同，请为修改后的内容包使用新ID。';return;}if(!$('reviewed').checked){$('importError').textContent='请先核对知识依据并勾选确认。';return;}packs=packs.filter(x=>x.id!==p.id);packs.push(p);updatePicker();$('modal').close();closeTask();load(p);toast('内容包已校验并装入；事实正确性仍需人工确认。');};
}
